import { approvedPublicClientProduct, parsePublicClientProductCatalog } from "./public-client-product";

describe("approved public client products", () => {
  test("approves both exact Twyne production origins", () => {
    expect(approvedPublicClientProduct("https://twyne.love")).toBe("twyne");
    expect(approvedPublicClientProduct("https://www.twyne.love")).toBe("twyne");
  });

  test("honors explicit Twyne loopback mappings without attributing other ports to Twyne", () => {
    const catalog = { "http://localhost:5173": "twyne" as const };
    expect(approvedPublicClientProduct("http://localhost:5173", catalog)).toBe("twyne");
    expect(approvedPublicClientProduct("http://localhost:5174", catalog)).toBe("keating");
    expect(approvedPublicClientProduct("http://127.0.0.1:5173", catalog)).toBe("keating");
  });

  test("accepts explicitly configured localhost, IPv4 and IPv6 Twyne development origins", () => {
    const catalog = parsePublicClientProductCatalog({
      "http://localhost:5173": "twyne",
      "http://127.0.0.1:5173": "twyne",
      "http://[::1]:5173": "twyne",
    });
    for (const origin of Object.keys(catalog)) {
      expect(approvedPublicClientProduct(origin, catalog)).toBe("twyne");
    }
    expect(approvedPublicClientProduct("http://localhost:5174", catalog)).toBe("keating");
  });

  test("catalog rejects wildcard approvals, URL paths, credentials and public HTTP", () => {
    for (const client of [
      "https://*.twyne.love", "http://192.168.1.2:5173",
      "http://localhost:5173/", "https://user@twyne.love", "https://twyne.love/path",
    ]) expect(() => parsePublicClientProductCatalog({ [client]: "twyne" })).toThrow();
    expect(() => parsePublicClientProductCatalog({ "https://twyne.love": "unknown" })).toThrow();
  });

  test("rejects Twyne lookalikes, subdomains, insecure public hosts and alternate ports", () => {
    for (const client of [
      "https://twyne.love.evil.example",
      "https://preview.twyne.love",
      "http://twyne.love",
      "https://www.twyne.love:8443",
      "https://user@www.twyne.love",
    ]) expect(() => approvedPublicClientProduct(client)).toThrow();
  });
});
