import { AsyncLocalStorage } from "node:async_hooks";
import { createHash } from "node:crypto";
import { resolve } from "node:path";
export const accountScope = new AsyncLocalStorage<string>();
export function accountKey(): string | undefined {
  const did = accountScope.getStore();
  return did ? createHash("sha256").update(did).digest("hex") : undefined;
}
export function accountPath(path: string, localPath: string): string {
  const key = accountKey();
  return key ? resolve(".baste/accounts", key, path) : resolve(localPath);
}
/**
 * Baste GUI Server - Web interface for managing personas and configs
 *
 * Serves a minimal HTML/JS frontend that communicates with the
 * Baste API (via the Flue agent or direct integration).
 */

import { createServer } from "node:http";
import { readFileSync, existsSync } from "node:fs";
import { resolve, join, sep } from "node:path";
import type { Server } from "node:http";
import { handleAPIRequest } from "./api.js";
import { accountEnabled, publicOrigin } from "../notorganic/server.js";

const GUI_ROOT = resolve(
  import.meta.dirname || ".",
  existsSync(resolve(import.meta.dirname || ".", "public"))
    ? "public"
    : "../../../src/gui/public"
);

function getMimeType(path: string): string {
  if (path.endsWith(".html")) return "text/html";
  if (path.endsWith(".js")) return "application/javascript";
  if (path.endsWith(".css")) return "text/css";
  if (path.endsWith(".json")) return "application/json";
  if (path.endsWith(".svg")) return "image/svg+xml";
  return "application/octet-stream";
}

function serveFile(res: any, path: string, status = 200): void {
  try {
    const content = readFileSync(path);
    res.writeHead(status, { "Content-Type": getMimeType(path) });
    res.end(content);
  } catch {
    res.writeHead(404, { "Content-Type": "text/plain" });
    res.end("Not found");
  }
}

export function createGUIServer(port = 3456): Server {
  const server = createServer((req, res) => {
    // Host validation prevents DNS rebinding against the local server and its keys.
    const allowedHosts = new Set([`localhost:${port}`, `127.0.0.1:${port}`, `[::1]:${port}`, new URL(publicOrigin()).host]);
    if (!req.headers.host || !allowedHosts.has(req.headers.host)) { res.writeHead(403); res.end("Invalid host"); return; }
    res.setHeader("X-Content-Type-Options", "nosniff");
    res.setHeader("Referrer-Policy", "same-origin");
    const url = new URL(req.url || "/", `http://localhost:${port}`);
    const pathname = url.pathname === "/" ? "/index.html" : url.pathname;
    const filePath = resolve(GUI_ROOT, `.${pathname}`);
    if (!filePath.startsWith(`${GUI_ROOT}${sep}`)) { res.writeHead(404); res.end("Not found"); return; }

    // API routes — handled by api.ts
    handleAPIRequest(req, res).then((isApi) => {
      if (isApi) return;

      // Static files
      if (existsSync(filePath)) {
        serveFile(res, filePath);
      } else {
        // Fallback to index.html for SPA routing
        const indexPath = join(GUI_ROOT, "index.html");
        if (existsSync(indexPath)) {
          serveFile(res, indexPath);
        } else {
          res.writeHead(404, { "Content-Type": "text/plain" });
          res.end("GUI not built. Run the build step first.");
        }
      }
    }).catch(() => {
      res.writeHead(500, { "Content-Type": "text/plain" });
      res.end("Internal server error");
    });
  });

  return server;
}

export async function startGUIServer(port = 3456): Promise<Server> {
  const server = createGUIServer(port);
  const started = await new Promise<Server>((resolve, reject) => {
    const host = process.env.BASTE_API_HOST ?? (accountEnabled() ? "127.0.0.1" : "127.0.0.1");
    if (!accountEnabled() && !["127.0.0.1", "localhost", "::1"].includes(host)) throw new Error("Local mode must bind to loopback. Enable Not Organic account mode before exposing the API.");
    server.listen(port, host, () => {
      console.log(`\n🌐 Baste GUI running at http://localhost:${port}`);
      resolve(server);
    });
    server.on("error", reject);
  });

  // Graceful shutdown on SIGINT
  process.on("SIGINT", () => {
    console.log("\n[gui] SIGINT received, closing server...");
    server.close(() => process.exit(0));
    // Force-exit after 5s in case of stuck connections
    setTimeout(() => process.exit(1), 5000);
  });

  return started;
}
/**
 * Persona Engine - Defines how we capture and model user personas
 *
 * A persona represents the perfect user of an application - their culture,
 * influences, obsessions, aesthetic preferences, and identity.
 *
 * From this persona, we generate design directions that make an app
 * feel uniquely tailored rather than generic.
 */

export interface Persona {
  id: string;
  name: string;
  summary: string;

  // Cultural & Identity anchors
  culture: CulturalIdentity;

  // Media & aesthetic influences
  influences: Influences;

  // Behavioral patterns
  behaviors: Behaviors;

  // Visual language preferences (extracted from above)
  aesthetic: AestheticProfile;
}

export interface CulturalIdentity {
  // Geographic/regional cultural context
  region?: string;
  // Subcultures they identify with
  subcultures: string[];
  // Values that drive their choices
  values: string[];
  // Languages, dialects, vernacular
  language?: {
    primary: string;
    vernacular: string[]; // slang, expressions they use
  };
}

export interface Influences {
  // Movies, TV shows, anime they love
  films: string[];
  shows: string[];
  anime: string[];

  // Music & audio culture
  music: {
    genres: string[];
    artists: string[];
  };

  // Games, interactive experiences
  games: string[];

  // Visual artists, designers, studios
  visualArtists: string[];

  // Fashion, brands, aesthetics
  fashion: string[];

  // Architecture, spaces, environments
  spaces: string[];

  // Tech/tools they love using
  tools: string[];

  // Nerdy obsessions - the deep dives
  obsessions: string[];
}

export interface Behaviors {
  // How they discover things
  discovery: string[];

  // What they value in interfaces
  interfaceValues: string[];

  // Their daily digital habitats
  platforms: string[];

  // How they express themselves
  expression: string[];

  // What annoys them about generic UIs
  petPeeves: string[];
}

export interface AestheticProfile {
  // Color tendencies (will be generated from persona)
  colorTemperature: "warm" | "cool" | "neutral" | "high-contrast" | "muted";
  density: "minimal" | "dense" | "rich" | "maximalist";
  edgeStyle: "sharp" | "soft" | "organic" | "geometric" | "brutalist";
  motionStyle: "smooth" | "snappy" | "liquid" | "mechanical";
  typographyStyle: "clean" | "expressive" | "retro" | "futuristic" | "handcrafted";
  textureStyle: "flat" | "textured" | "noisy" | "clean" | "grainy";
  iconStyle: "line" | "filled" | "hand-drawn" | "geometric" | "abstract";
  layoutStyle: "grid" | "organic" | "asymmetric" | "brutalist" | "editorial";

  // Generated keywords for prompting
  visualKeywords: string[];
  moodKeywords: string[];
}

/**
 * Extract aesthetic profile from full persona using keyword inference.
 */
export function extractAestheticFromPersona(persona: Persona): AestheticProfile {
  const keywords = generateVisualKeywords(persona);

  return {
    colorTemperature: inferColorTemperature(persona),
    density: inferDensity(persona),
    edgeStyle: "soft",
    motionStyle: "smooth",
    typographyStyle: "expressive",
    textureStyle: "textured",
    iconStyle: "line",
    layoutStyle: "organic",
    visualKeywords: keywords.visual,
    moodKeywords: keywords.mood,
  };
}

function generateVisualKeywords(persona: Persona): { visual: string[]; mood: string[] } {
  const influences = persona.influences;
  const keywords: string[] = [];
  const moods: string[] = [];

  // Extract from media influences
  keywords.push(
    ...influences.films.slice(0, 3),
    ...influences.anime.slice(0, 3),
    ...influences.visualArtists.slice(0, 3)
  );

  // Add subculture visual language
  keywords.push(...persona.culture.subcultures.slice(0, 3));

  // Add fashion/space aesthetics
  keywords.push(
    ...influences.fashion.slice(0, 2),
    ...influences.spaces.slice(0, 2)
  );

  // Generate moods from values and behaviors
  moods.push(...persona.culture.values.slice(0, 4));
  moods.push(...persona.behaviors.interfaceValues.slice(0, 3));

  return {
    visual: [...new Set(keywords)].filter(Boolean),
    mood: [...new Set(moods)].filter(Boolean),
  };
}

function inferColorTemperature(persona: Persona): AestheticProfile["colorTemperature"] {
  const allText = JSON.stringify(persona).toLowerCase();

  if (/warm|sun|desert|orange|amber|gold|earth|terracotta/.test(allText)) return "warm";
  if (/cool|ice|blue|cyan|teal|ocean|night/.test(allText)) return "cool";
  if (/contrast|bold|black.*white|monochrome/.test(allText)) return "high-contrast";
  if (/pastel|soft|pink|cream|beige/.test(allText)) return "muted";

  return "neutral";
}

function inferDensity(persona: Persona): AestheticProfile["density"] {
  const allText = JSON.stringify(persona).toLowerCase();

  if (/minimal|clean|simple|space|breathing|white|empty/.test(allText)) return "minimal";
  if (/maximal|clutter|busy|pattern|rich|dense|full/.test(allText)) return "maximalist";
  if (/information|data|dashboard|tool|editor/.test(allText)) return "dense";

  return "rich";
}
/**
 * Persona Store - Unified registry for built-in and custom personas
 *
 * Built-in personas ship with the library as templates.
 * Custom personas are loaded from JSON files in a user-defined directory.
 *
 * Priority: Custom personas override built-in personas with the same id.
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, unlinkSync } from "node:fs";
import { resolve, join, dirname } from "node:path";
import type { Persona } from "./types.js";
import { basePersonas } from "./base-personas.js";

const DEFAULT_CUSTOM_DIR = resolve(process.cwd(), "personas");

export interface StoreConfig {
  /** Directory to load/save custom personas */
  customDir?: string;
}

let storeConfig: StoreConfig = { customDir: DEFAULT_CUSTOM_DIR };
let customPersonas: Map<string, Persona> = new Map();
let initialized = false;

/** Ensure custom personas directory exists */
function ensureDir(dir: string): void {
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

/** Load all custom persona JSON files from the directory */
function loadCustomPersonas(dir: string): Map<string, Persona> {
  const map = new Map<string, Persona>();
  if (!existsSync(dir)) return map;

  const files = readdirSync(dir).filter((f) => f.endsWith(".json"));
  for (const file of files) {
    try {
      const content = readFileSync(join(dir, file), "utf-8");
      const persona: Persona = JSON.parse(content);
      if (persona.id) {
        map.set(persona.id, persona);
      }
    } catch (err) {
      console.warn(`[persona/store] Skipping invalid file ${file}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  return map;
}

/** Initialize or reinitialize the store */
export function initStore(config?: StoreConfig): void {
  storeConfig = {
    customDir: config?.customDir
      ? resolve(config.customDir)
      : storeConfig.customDir,
  };
  ensureDir(storeConfig.customDir!);
  customPersonas = loadCustomPersonas(storeConfig.customDir!);
  initialized = true;
}

/** Get the custom personas directory path */
export function getCustomDir(): string {
  if (!initialized) initStore();
  return storeConfig.customDir!;
}

/** Look up a persona by id. Custom personas take priority over built-in. */
export function getPersona(id: string): Persona | undefined {
  if (!initialized) initStore();
  return customPersonas.get(id) ?? basePersonas[id];
}

/** List all persona ids. */
export function listPersonas(): string[] {
  if (!initialized) initStore();
  const baseIds = Object.keys(basePersonas);
  const customIds = Array.from(customPersonas.keys());
  return [...new Set([...baseIds, ...customIds])];
}

/** Check if a persona is built-in. */
export function isBasePersona(id: string): boolean {
  return id in basePersonas;
}

/** Check if a persona is custom (user-defined). */
export function isCustomPersona(id: string): boolean {
  if (!initialized) initStore();
  return customPersonas.has(id);
}

/** Save a custom persona to disk. Overwrites existing. */
export function savePersona(persona: Persona): void {
  if (!initialized) initStore();
  const dir = storeConfig.customDir!;
  ensureDir(dir);
  const path = join(dir, `${persona.id}.json`);
  writeFileSync(path, JSON.stringify(persona, null, 2));
  customPersonas.set(persona.id, persona);
}

/** Delete a custom persona. Built-in personas cannot be deleted. */
export function deletePersona(id: string): boolean {
  if (!initialized) initStore();
  if (isBasePersona(id)) return false;
  if (!customPersonas.has(id)) return false;

  const path = join(storeConfig.customDir!, `${id}.json`);
  if (existsSync(path)) {
    unlinkSync(path);
  }
  customPersonas.delete(id);
  return true;
}

/** Get all built-in personas. */
export function getBasePersonas(): Record<string, Persona> {
  return { ...basePersonas };
}

/** Get all custom personas. */
export function getCustomPersonas(): Record<string, Persona> {
  if (!initialized) initStore();
  return Object.fromEntries(customPersonas);
}

/** Get the file path for a custom persona. */
export function getPersonaPath(id: string): string | undefined {
  if (!initialized) initStore();
  if (!customPersonas.has(id)) return undefined;
  return join(storeConfig.customDir!, `${id}.json`);
}

