import { component$, useContext } from "@builder.io/qwik";
import { css } from "styled-system/css";
import { StudioCtx, openView, selectPersona } from "./context";
import { kicker } from "./ui";

export const Rail = component$(() => {
  const s = useContext(StudioCtx);
  const base = s.personas.filter((p) => p._source !== "custom");
  const custom = s.personas.filter((p) => p._source === "custom");

  const group = (title: string, list: typeof s.personas) => (
    <div class={css({ display: "flex", flexDirection: "column", gap: 1 })}>
      <h2 class={kicker} style={{ padding: "0 10px", marginBottom: "4px" }}>{title}</h2>
      <ul class={css({ listStyle: "none", display: "flex", flexDirection: "column", gap: "2px" })}>
        {list.map((p) => {
          const t = s.tokens[p.id];
          const current = s.view === "persona" && s.selectedId === p.id;
          return (
            <li key={p.id}>
              <button
                type="button"
                aria-current={current ? "true" : undefined}
                onClick$={() => selectPersona(s, p.id)}
                class={css({
                  w: "100%",
                  display: "grid",
                  gridTemplateColumns: "34px 1fr",
                  gap: 3,
                  alignItems: "center",
                  p: "8px 10px",
                  rounded: "base",
                  textAlign: "left",
                  bg: "transparent",
                  border: "1px solid transparent",
                  cursor: "pointer",
                  transition: "background 0.15s",
                  _hover: { bg: "paper-deep" },
                  "&[aria-current=true]": { bg: "card", borderColor: "rule", boxShadow: "sheet" },
                })}
              >
                <span
                  aria-hidden="true"
                  class={css({ position: "relative", w: "34px", h: "34px", rounded: "sm", overflow: "hidden", border: "1px solid rgba(28,27,25,0.12)" })}
                  style={{ background: t?.colors.background ?? "#E7E0D2" }}
                >
                  {t && (
                    <>
                      <i class={css({ position: "absolute", left: "6px", top: "6px", w: "14px", h: "14px", rounded: "full" })} style={{ background: t.colors.primary }} />
                      <i class={css({ position: "absolute", right: "5px", bottom: "5px", w: "10px", h: "10px", rounded: "xs" })} style={{ background: t.colors.secondary }} />
                    </>
                  )}
                </span>
                <span class={css({ minW: 0 })}>
                  <span class={css({ display: "block", fontSize: "14px", fontWeight: 600, color: "ink", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" })}>
                    {p.name.replace(/^The /, "")}
                  </span>
                  <span class={css({ display: "block", fontFamily: "mono", fontSize: "11px", color: "ink-muted", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" })}>
                    {p.aesthetic?.colorTemperature} · {p.aesthetic?.density}
                  </span>
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );

  const action = (label: string, view: "new" | "decompose" | "remix", glyph: string, desc: string) => (
    <button
      type="button"
      aria-current={s.view === view ? "true" : undefined}
      onClick$={() => openView(s, view)}
      class={css({
        w: "100%",
        display: "grid",
        gridTemplateColumns: "26px 1fr",
        gap: 3,
        alignItems: "center",
        p: "8px 10px",
        rounded: "base",
        textAlign: "left",
        bg: "transparent",
        border: "1px solid transparent",
        cursor: "pointer",
        _hover: { bg: "paper-deep" },
        "&[aria-current=true]": { bg: "card", borderColor: "rule" },
      })}
    >
      <span aria-hidden="true" class={css({ display: "grid", placeItems: "center", w: "26px", h: "26px", rounded: "full", border: "1px dashed token(colors.rule-strong)", fontSize: "14px", color: "thread-ink" })}>
        {glyph}
      </span>
      <span>
        <span class={css({ display: "block", fontSize: "14px", fontWeight: 600 })}>{label}</span>
        <span class={css({ display: "block", fontSize: "12px", color: "ink-muted" })}>{desc}</span>
      </span>
    </button>
  );

  return (
    <>
      {s.railOpen && (
        <div
          aria-hidden="true"
          onClick$={() => (s.railOpen = false)}
          class={css({ position: "fixed", inset: 0, top: "56px", bg: "rgba(28,27,25,0.32)", zIndex: 30, display: { lg: "none" } })}
        />
      )}
      <nav
        id="studio-rail"
        aria-label="Wardrobe"
        data-open={s.railOpen ? "true" : "false"}
        class={css({
          position: { base: "fixed", lg: "sticky" },
          top: "56px",
          left: 0,
          bottom: { base: 0, lg: "auto" },
          zIndex: 35,
          w: { base: "min(300px, 86vw)", lg: "auto" },
          h: { lg: "calc(100dvh - 56px)" },
          overflowY: "auto",
          bg: "paper",
          borderRight: "1px solid token(colors.rule)",
          p: 3,
          display: "flex",
          flexDirection: "column",
          gap: 6,
          transition: "transform 0.3s token(easings.thread)",
          transform: { base: "translateX(-105%)", lg: "none" },
          "&[data-open=true]": { transform: "none" },
        })}
      >
        {s.loading && s.personas.length === 0 ? (
          <div class={css({ display: "flex", flexDirection: "column", gap: 2, p: 2 })} aria-busy="true" aria-label="Loading personas">
            {[0, 1, 2].map((i) => (
              <div key={i} class={css({ h: "50px", rounded: "base", bg: "paper-deep", opacity: 0.7 })} />
            ))}
          </div>
        ) : (
          <>
            {group("Wardrobe", base)}
            {custom.length > 0 && group("Bespoke", custom)}
          </>
        )}

        <div class={css({ display: "flex", flexDirection: "column", gap: 1, mt: "auto", pt: 4, borderTop: "1px dashed token(colors.rule-strong)" })}>
          <h2 class={kicker} style={{ padding: "0 10px", marginBottom: "4px" }}>Start a fitting</h2>
          {action("New persona", "new", "+", "Write one from scratch")}
          {action("Decompose a site", "decompose", "⌗", "Draft from a live URL")}
          {action("Remix two", "remix", "×", "Cross two personas")}
        </div>
      </nav>
    </>
  );
});
import { component$, useContext, useVisibleTask$ } from "@builder.io/qwik";
import { css } from "styled-system/css";
import { StudioCtx, errMsg, loadTokens, openView, refreshPersonas, syncUrl, toast, type PersonaTab } from "./context";
import { btn, btnSm, emptyBox, kicker } from "./ui";
import { FittingTab } from "./tabs/fitting";
import { TokensTab } from "./tabs/tokens";
import { GenerateTab } from "./tabs/generate";
import { MoodboardTab } from "./tabs/moodboard";
import { BrandKitTab } from "./tabs/brandkit";
import { FeedbackTab } from "./tabs/feedback";
import { EditorTab } from "./tabs/editor";
import { Fabric, lookFromTokens } from "~/components/fx/fabric";
import { HoldButton } from "./hold-button";

const TABS: Array<{ id: PersonaTab; label: string }> = [
  { id: "fitting", label: "Fitting" },
  { id: "tokens", label: "Tokens" },
  { id: "generate", label: "Generate" },
  { id: "moodboard", label: "Moodboard" },
  { id: "brandkit", label: "Brand kit" },
  { id: "feedback", label: "Taste" },
  { id: "editor", label: "OpenPencil" },
];

export const Workspace = component$(() => {
  const s = useContext(StudioCtx);
  const persona = s.personas.find((p) => p.id === s.selectedId);
  const tokens = persona ? s.tokens[persona.id] : undefined;

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track }) => {
    const id = track(() => s.selectedId);
    track(() => s.status);
    if (id) loadTokens(s, id);
  });

  if (s.status === "connecting" || (s.loading && !persona)) {
    return (
      <div aria-busy="true" class={css({ display: "flex", flexDirection: "column", gap: 4 })}>
        <div class={css({ h: "120px", rounded: "lg", bg: "paper-deep", opacity: 0.6 })} />
        <div class={css({ h: "360px", rounded: "lg", bg: "paper-deep", opacity: 0.4 })} />
      </div>
    );
  }

  if (!persona) {
    if (s.account.status?.configured && !s.account.status.authenticated) return (
      <div class={emptyBox}>
        <h1 class="display" style={{ fontSize: "34px" }}>Connect your workroom.</h1>
        <p>Sign in or create a Not Organic profile to open your personas, models and wallet on this server.</p>
        <button class={btn("primary")} onClick$={() => openView(s, "settings")}>Sign in / create profile</button>
      </div>
    );
    return (
      <div class={emptyBox}>
        <h1 class="display" style={{ fontSize: "34px" }}>The wardrobe is empty.</h1>
        <p>Measure a new persona, or draft one from a site you admire.</p>
        <div class={css({ display: "flex", gap: 2, flexWrap: "wrap" })}>
          <button class={btn("primary")} onClick$={() => openView(s, "new")}>New persona</button>
          <button class={btn("secondary")} onClick$={() => openView(s, "decompose")}>Decompose a site</button>
        </div>
      </div>
    );
  }

  const custom = persona._source === "custom";

  return (
    <div class={css({ display: "flex", flexDirection: "column", gap: 6, maxW: "1280px" })}>
      {/* Persona header: a strip of the persona's own cloth behind its name */}
      <header class={css({ position: "relative", rounded: "lg", overflow: "hidden", border: "1px solid token(colors.rule)", bg: "card", boxShadow: "sheet" })}>
        <div class={css({ position: "absolute", inset: 0, opacity: 0.9 })} aria-hidden="true">
          {tokens && <Fabric look={lookFromTokens(tokens, persona.aesthetic.density)} quality={0.5} />}
        </div>
        <div
          class={css({ position: "relative", m: { base: 3, md: 4 }, ml: { md: "auto" }, maxW: { md: "min(720px, 72%)" }, p: { base: 4, md: 6 }, rounded: "base", display: "flex", flexDirection: "column", gap: 3 })}
          style={{ background: "rgba(251,249,244,0.94)", backdropFilter: "blur(6px)", boxShadow: "0 12px 30px -12px rgba(20,14,6,0.4)" }}
        >
          <div class={css({ display: "flex", alignItems: "center", gap: 2, flexWrap: "wrap" })}>
            <span class={kicker}>{custom ? "Bespoke persona" : "Base persona"}</span>
            <span class={css({ fontFamily: "mono", fontSize: "11.5px", color: "ink-muted" })}>· {persona.id}</span>
          </div>
          <h1 class="display" style={{ fontSize: "clamp(30px, 3.6vw, 46px)" }}>{persona.name}</h1>
          <p class={css({ color: "ink-soft", fontSize: "15px", maxW: "62ch" })}>{persona.summary}</p>
          <div class={css({ display: "flex", gap: 2, flexWrap: "wrap", mt: 1 })}>
            <button class={btn("primary", btnSm)} onClick$={() => { s.tab = "generate"; syncUrl(s); }}>Generate assets</button>
            <button class={btn("secondary", btnSm)} onClick$={() => openView(s, custom ? "edit" : "tailor")}>
              {custom ? "Edit measurements" : "Tailor a copy"}
            </button>
            {custom && (
              <HoldButton
                label="Unpick"
                holdingLabel="Unpicking…"
                onConfirm$={async () => {
                  if (!s.client) return;
                  try {
                    await s.client.deletePersona(persona.id);
                    toast(s, `Unpicked ${persona.name} — personas/${persona.id}.json removed`);
                    s.selectedId = "";
                    await refreshPersonas(s);
                  } catch (err) {
                    toast(s, errMsg(err), "error");
                  }
                }}
              />
            )}
          </div>
        </div>
      </header>

      {/* Tabs */}
      <div
        role="tablist"
        aria-label="Persona workspace"
        class={css({ display: "flex", gap: 1, overflowX: "auto", borderBottom: "1px solid token(colors.rule)", scrollbarWidth: "none", maskImage: { base: "linear-gradient(90deg, #000 85%, transparent)", md: "none" } })}
      >
        {TABS.map((t) => (
          <button
            key={t.id}
            role="tab"
            id={`tab-${t.id}`}
            aria-selected={s.tab === t.id}
            aria-controls="persona-tabpanel"
            onClick$={() => {
              s.tab = t.id;
              syncUrl(s);
            }}
            class={css({
              position: "relative",
              flexShrink: 0,
              h: "42px",
              px: 3,
              fontSize: "14px",
              color: "ink-muted",
              bg: "transparent",
              border: 0,
              _hover: { color: "ink" },
              "&[aria-selected=true]": { color: "ink", fontWeight: 600 },
              "&[aria-selected=true]::after": {
                content: '""',
                position: "absolute",
                left: 3,
                right: 3,
                bottom: "-1px",
                h: "2px",
                backgroundImage: "linear-gradient(90deg, token(colors.thread) 0 7px, transparent 7px 11px)",
                backgroundSize: "11px 2px",
              },
            })}
          >
            {t.label}
          </button>
        ))}
      </div>

      <div id="persona-tabpanel" role="tabpanel" aria-labelledby={`tab-${s.tab}`} key={`${persona.id}-${s.tab}`} class="rise">
        {s.tab === "fitting" && <FittingTab />}
        {s.tab === "tokens" && <TokensTab />}
        {s.tab === "generate" && <GenerateTab />}
        {s.tab === "moodboard" && <MoodboardTab />}
        {s.tab === "brandkit" && <BrandKitTab />}
        {s.tab === "feedback" && <FeedbackTab />}
        {s.tab === "editor" && <EditorTab />}
      </div>
    </div>
  );
});
