    let data: unknown;
    try { data = raw ? JSON.parse(raw) : undefined; }
    catch {
      if (response.ok) throw new Error('Baste server returned invalid JSON');
    }
    if (!response.ok) {
      const message = data && typeof data === 'object' && 'error' in data && typeof data.error === 'string'
        ? data.error
